document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("fence-form"),n=document.getElementById("fence-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("fence-length").value),s=parseFloat(document.getElementById("fence-height").value),[a,i]=document.getElementById("fence-type").value.split(","),o=parseFloat(document.getElementById("fence-spacing").value),p=parseFloat(document.getElementById("fence-gates").value),l=parseFloat(document.getElementById("fence-gate-width").value),r=parseFloat(document.getElementById("fence-terrain").value);if(t<=0)return n.textContent="Please enter a valid fence length.",void 0;const c=Math.floor(t/o)+1,d=2*p,g=c+d-(p>0?p:0),u=(Math.ceil(t/o),t-p*l);let h={},$=1;switch(a){case"wood-privacy":h={posts:g,rails:3*Math.ceil(u/8),pickets:Math.ceil(12*u/6),concrete:1.5*g,screws:2*Math.ceil(u/8)},$=1.2;break;case"wood-picket":h={posts:g,rails:2*Math.ceil(u/8),pickets:Math.ceil(12*u/4),concrete:1.5*g,screws:1.5*Math.ceil(u/8)},$=1.1;break;case"vinyl":h={posts:g,panels:Math.ceil(u/8),concrete:1.5*g,brackets:2*Math.ceil(u/8)},$=1;break;case"chain-link":h={posts:g,fabric:Math.ceil(u),rails:Math.ceil(u/10),concrete:1*g,ties:Math.ceil(8*u)},$=.9;break;case"aluminum":case"steel":h={posts:g,panels:Math.ceil(u/6),concrete:1.5*g,brackets:4*Math.ceil(u/6)},$=1.1}const m=u*parseFloat(i),v=p*l*parseFloat(i)*1.5,f=150*p,k=(m+v+f)*r,y=t/20*s*$*r,b=75*y,F=s/3+.5,w=g*F;let M="";switch(a){case"wood-privacy":case"wood-picket":M="4×4 pressure-treated posts";break;case"vinyl":M="4×4 vinyl or aluminum posts";break;case"chain-link":M='2-3/8" galvanized steel posts';break;case"aluminum":case"steel":M='3×3" aluminum/steel posts'}n.innerHTML=`\n        <div class="result-section">\n          <h4>Fence Specifications:</h4>\n          <p>Total fence length: ${t} linear feet</p>\n          <p>Fence height: ${s} feet</p>\n          <p>Fence type: ${a.replace("-"," ")}</p>\n          <p>Post spacing: ${o} feet on center</p>\n          <p>Actual fence length: ${u} ft (minus ${p} gates)</p>\n        </div>\n        \n        <div class="result-posts">\n          <h4>Posts & Foundation:</h4>\n          <p><strong>${g} ${M}</strong></p>\n          <p>- ${c} line posts</p>\n          ${d>0?`<p>- ${d} gate posts</p>`:""}\n          <p><strong>Post holes: ${g} holes, ${F.toFixed(1)}' deep</strong></p>\n          <p>Concrete needed: ${h.concrete||0} bags (50 lb fast-set)</p>\n          <p>Total digging: ${w.toFixed(1)} cubic feet</p>\n        </div>\n        \n        <div class="result-materials">\n          <h4>Fence Materials:</h4>\n          ${a.includes("wood")?`\n          <p><strong>Rails:</strong> ${h.rails||0} pieces (2×4 × 8')</p>\n          <p><strong>Pickets:</strong> ${h.pickets||0} pieces</p>\n          <p><strong>Screws:</strong> ${h.screws||0} lbs galvanized</p>\n          `:""}\n          ${"vinyl"===a?`\n          <p><strong>Panels:</strong> ${h.panels||0} vinyl panels</p>\n          <p><strong>Brackets:</strong> ${h.brackets||0} mounting brackets</p>\n          `:""}\n          ${"chain-link"===a?`\n          <p><strong>Fabric:</strong> ${h.fabric||0} linear feet</p>\n          <p><strong>Top rail:</strong> ${h.rails||0} pieces</p>\n          <p><strong>Ties:</strong> ${h.ties||0} chain link ties</p>\n          `:""}\n          ${"aluminum"===a||"steel"===a?`\n          <p><strong>Panels:</strong> ${h.panels||0} metal panels</p>\n          <p><strong>Brackets:</strong> ${h.brackets||0} mounting brackets</p>\n          `:""}\n        </div>\n        \n        ${p>0?`\n        <div class="result-gates">\n          <h4>Gate Materials:</h4>\n          <p><strong>${p} gates</strong> (${l}' wide each)</p>\n          <p>Gate frames: ${p} complete gate sets</p>\n          <p>Hinges: ${2*p} heavy-duty hinges</p>\n          <p>Latches: ${p} gate latches</p>\n          <p>Hardware cost: $${f}</p>\n        </div>\n        `:""}\n        \n        <div class="result-costs">\n          <h4>Cost Breakdown:</h4>\n          <p>Fence materials: $${m.toFixed(0)}</p>\n          ${p>0?`<p>Gate materials: $${v.toFixed(0)}</p>`:""}\n          ${p>0?`<p>Gate hardware: $${f}</p>`:""}\n          ${r>1?`<p>Terrain adjustment: ${(100*(r-1)).toFixed(0)}%</p>`:""}\n          <p><strong>Total materials: $${k.toFixed(0)}</strong></p>\n          <p>Professional labor: $${b.toFixed(0)}</p>\n          <p><strong>Total project cost: $${(k+b).toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Timeline:</h4>\n          <p>Estimated labor: ${y.toFixed(1)} hours</p>\n          <p>DIY timeline: ${Math.ceil(y/8)} days (8 hrs/day)</p>\n          <p>Professional: ${Math.ceil(y/16)} days (2-person crew)</p>\n          <p>Post setting: allow 24-48 hours cure time</p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools Required:</h4>\n          <p>🕳️ Post hole digger or auger</p>\n          <p>📏 Level and measuring tape</p>\n          <p>🔨 Drill and impact driver</p>\n          <p>⚡ Circular saw or miter saw</p>\n          <p>🧤 Safety equipment (gloves, glasses)</p>\n          <p>📐 String line and stakes</p>\n        </div>\n        \n        <div class="result-permits">\n          <h4>Before You Start:</h4>\n          <p>📞 Call 811 for utility marking (required)</p>\n          <p>📋 Check local fence permits and codes</p>\n          <p>📏 Verify property lines and setbacks</p>\n          <p>🤝 Discuss with neighbors (shared fence lines)</p>\n          <p>🌦️ Check weather forecast (avoid wet conditions)</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Money-Saving Tips:</h4>\n          <p>💰 DIY installation saves 50% on labor</p>\n          <p>📦 Buy materials in bulk for discounts</p>\n          <p>⏰ Shop off-season for better prices</p>\n          <p>🔧 Rent specialized tools vs buying</p>\n          <p>👥 Get multiple contractor quotes</p>\n        </div>\n      `})});